import {moduleOf,simulate,assess,KEYS,META} from './model.mjs';
export function inverseTime(x,target,eq,k){if(target>=x)return 0;if(k<=0||target<=eq)return Infinity;return Math.log((x-eq)/(target-eq))/k;}
export function planRoutes(state){
 const invalid=simulate(state);if(invalid.errors.length)return {errors:invalid.errors,candidates:[]};
 const stainless=state.grade.startsWith('SS');
 const routes=stainless?[['AOD','LF','SOFT'],['AOD','VOD','LF','SOFT']]:[['LF','SOFT'],['LF','VD','SOFT'],['LF','RH','SOFT']];
 const candidates=[];
 for(const route of routes){let best=null;for(const scale of [0.5,0.75,1,1.5,2,3]){const s=structuredClone(state);s.modules=route.map(type=>{const m=moduleOf(type);m.time=Math.min(180,Math.ceil(m.time*scale));m.heat=Math.min(m.heat,m.time);m.powderTime=Math.min(m.powderTime,m.time);if(type==='VD')m.desulf=true;return m;});const r=simulate(s);const checks=assess(s,r),failed=checks.filter(x=>!x.ok);const penalty=failed.reduce((sum,a)=>sum+(Array.isArray(a.target)?Math.max(a.target[0]-a.value,a.value-a.target[1],0)/Math.max(.001,a.target[1]):Math.max(0,a.value-a.target)/Math.max(.001,a.target)),0);const candidate={state:s,result:r,checks,failed,penalty,scale};if(!best||(!failed.length&&best.failed.length)||((!failed.length===!best.failed.length)&&(penalty<best.penalty-1e-9||(Math.abs(penalty-best.penalty)<1e-9&&r.time<best.result.time))))best=candidate;}candidates.push(best);}
 candidates.sort((a,b)=>a.failed.length===0&&b.failed.length? -1:b.failed.length===0&&a.failed.length?1:a.penalty-b.penalty||a.result.time-b.result.time);return {errors:[],candidates};
}
const fmt=(v)=>Number(v).toFixed(2);
export function mountPlanner({getState,apply}){const host=document.querySelector('#planner');let latest=[];
 host.addEventListener('change',e=>e.stopPropagation());host.addEventListener('input',e=>e.stopPropagation());
 function refresh(){host.innerHTML=`<p>从当前电炉出钢成分出发，以当前研究目标为终点，比较有限候选路线及 0.5–3 倍处理时间。输入成分与目标后点击计算。不会自动改变现有流程。</p><div class="planner-inputs">${KEYS.map(k=>`<label>${k==='O'?'总氧 T.O':k} 终点${k==='C'?'上限 %':'上限 ppm'}<input type="number" min="0" step="${k==='C'?'.001':'.1'}" data-plan-target="${k}" value="${Array.isArray(getState().targets[k])?getState().targets[k][1]:getState().targets[k]}"></label>`).join('')}</div><button class="button" id="run-planner">按当前起点和目标比较路线</button><div id="planner-results"></div>${physics()}`;}
 host.addEventListener('click',e=>{if(e.target.id==='run-planner'){const s=structuredClone(getState());for(const input of host.querySelectorAll('[data-plan-target]')){const k=input.dataset.planTarget,v=input.valueAsNumber;if(!Number.isFinite(v)||v<0||v>(k==='C'?5:5000)){host.querySelector('#planner-results').textContent='终点输入无效，请输入非负且在模型范围内的数值。';return;}if(k==='C'){if(v<s.targets.C[0]){host.querySelector('#planner-results').textContent='碳上限不能小于当前碳下限。';return;}s.targets.C[1]=v;}else s.targets[k]=v;}const p=planRoutes(s);latest=p.candidates;host.querySelector('#planner-results').innerHTML=p.errors.length?p.errors.join('；'):latest.map((c,i)=>`<article class="planner-card"><h3>${c.state.modules.map(m=>META[m.type].short).join(' → ')} · ${fmt(c.result.time)} min</h3><p>${c.failed.length?'候选搜索未满足：'+c.failed.map(x=>x.key).join('、'):'5 项代理指标在当前研究目标内'} · 含电炉与准备时间；不是最优工艺证明。</p><p>${KEYS.map(k=>`${k==='O'?'T.O':k}：${fmt(s.initial[k])} → ${fmt(c.result.final[k])}${k==='C'?'%':' ppm'}`).join(' ｜ ')}</p><div class="table-scroll"><table><thead><tr><th>工序</th><th>有效 / 总时间 min</th>${['S','O','C','H'].map(k=>`<th>${k} 本段去除率</th>`).join('')}</tr></thead><tbody>${c.result.rows.filter(r=>r.type).map(r=>`<tr><td>${META[r.type].short}</td><td>${c.state.modules.find(m=>m.id===r.id).time} / ${fmt(r.duration)}</td>${['S','O','C','H'].map(k=>`<td>${r.before[k]>0?fmt(100*(r.before[k]-r.after[k])/r.before[k])+'%':'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><button class="button light" data-use-plan="${i}">采用此候选，查看时间及物料</button></article>`).join('')+'<p class="explain-box">N 尚无脱氮动力学，保持输入值；碳不足不会自动增碳。极低 S 可能受渣量 / 分配比约束，延长时间不能突破平衡。搜索未满足仅表示本候选集无解，不等于工业不可行。未评定温度路径、Cr / Ni / Mo、成本及设备产能。</p>';}
 if(e.target.dataset.usePlan!==undefined){const c=latest[Number(e.target.dataset.usePlan)];if(c)apply(c.state);}});refresh();return {refresh};}
function physics(){return `<div class="planner-physics"><h3>物理化学与动力学核对</h3><p><b>平衡：</b>K(T) = exp[−ΔG°/(RT)]，ΔG = ΔG° + RT ln Q；T 必须为 K，R = 8.314 J/(mol·K)。缺少标准自由能与活度模型时不计算真实反应平衡。</p><p><b>传质控制：</b>dX/dt = −k_eff(X−Xeq)，X(t) = Xeq + (X₀−Xeq)e^(−k_eff t)；t = ln[(X₀−Xeq)/(Xtarget−Xeq)]/k_eff。k_eff 单位 min⁻¹，可理解为 k_m A/V；目标 ≤ 平衡值时不存在有限去除时间。多反应、温度及面积变化时需积分求解。</p><p><b>脱硫：</b>[S]+(O²⁻) ⇌ (S²⁻)+[O]；L_S = (S)%/[S]%，本模型 S_eq = (m钢·S钢 + m渣·S渣)/(m钢 + L_S·m渣)。低溶解氧活度与高硫容量渣有利脱硫。现模型以 T.O ≤ 60 ppm 代替脱氧门槛，仅为粗略代理，T.O 不等于溶解氧，不能用于求真实 L_S。</p><p><b>脱碳及供氧约束：</b>[C]+[O] ⇌ CO(g)，K = pCO/(aC·aO)。按生成 CO，1 Nm³ O₂ 理论最多氧化 24/22.414 kg C；模型取供氧利用率 0.8，忽略合金竞争氧化，故不能用于不锈钢保铬定量设计。</p><p><b>脱氢：</b>[H] ⇌ ½H₂(g)，平衡遵循 aH = K_H(T)√pH₂；本模型固定 H 平衡底限，真空总压不等于氢分压。</p><p><b>参数标识：</b>LF kS=0.025；VD kH=0.12；RH kH=0.10；AOD kC=0.14；VOD kC=0.10 min⁻¹，均为教学假设，未由论文拟合。LF总氧代理 k=0.10×铝量；软吹 k=0.045 并带气量修正，也不是化学脱氧平衡。温度工具提供解释，当前反应速率未与温度耦合，不能据此预测调温增益。</p><p>参考：<a href="https://doi.org/10.1002/srin.202200965" target="_blank" rel="noopener">2023 LF 界面平衡与脱硫 CFD</a>；<a href="https://doi.org/10.2355/isijinternational.ISIJINT-2021-514" target="_blank" rel="noopener">2022 传热、流动与脱硫动力学耦合</a>；<a href="https://doi.org/10.1002/srin.202300330" target="_blank" rel="noopener">2024 Si–Mn 钢脱氧 / 脱硫模型</a>。这些文献支持建模方法，不是上述假定常数的来源。</p></div>`;}

